  const toggle = async (enabled: boolean) => { try { setFailure(false); setBusy(true); setMessage(enabled ? 'Enabling cwebp…' : 'Disabling cwebp…'); await window.vhostra?.configureCwebp(enabled); await refresh(); await load(); setMessage(enabled ? 'cwebp is installed and verified.' : 'cwebp is disabled and removed from the running Vhostra runtime.') } catch (reason) { setFailure(true); setMessage(errorText(reason)) } finally { setBusy(false) } }
