  const shown = displayedConfiguration(settings, pendingSettings)
  const operationMessage = configurationOperationMessage(activeOperation?.intent ?? [])
  useEffect(() => { void window.vhostra?.getStorageLayout().then(value => setLayout(value ?? null)).catch(reason => { setFailure(true); setNotice(errorText(reason)) }) }, [])
  const save = async (next: VhostraSettings, action?: string) => { setPendingAction(action ?? 'Saving'); if (action) setRuntimeOutcome(`${action}…`); setFailure(false); setNotice(null); try { await runConfiguration(next, () => window.vhostra!.saveSettings(next)); setNotice('Preferences saved locally.'); if (action) setRuntimeOutcome(`${action} completed and verified.`) } catch (reason) { setFailure(true); setNotice(errorText(reason)); if (action) setRuntimeOutcome(`${action} failed. The previous verified setting was restored.`) } finally { setPendingAction(null) } }
